class Solution {
public:
    string makeGood(string s) {
        string res;
        for (char ch : s) {
            if (!res.empty() && abs(res.back() - ch) == 32) {
                res.pop_back();
            } else {
                res.push_back(ch);
            }
        }
        return res;
    }
};

class Solution {
    public String makeGood(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            int len = sb.length();
            if (len > 0 && Math.abs(sb.charAt(len - 1) - ch) == 32) {
                sb.deleteCharAt(len - 1);
            } else {
                sb.append(ch);
            }
        }
        return sb.toString();
    }
}

var makeGood = function(s) {
    const st = [];
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (st.length > 0 && Math.abs(st[st.length - 1].charCodeAt(0) - ch.charCodeAt(0)) === 32) {
            st.pop();
        } else {
            st.push(ch);
        }
    }
    return st.join('');
};
